SELECT COUNT(*) /* SQL_ID: RdfMappingMapper.selectRdfMappingStatusCount */ FROM ( SELECT rdf_form_mtcd_nm, mtcd, model_id, model_nm FROM ( SELECT m2.mtcd_nm AS rdf_form_mtcd_nm, m2.mtcd AS mtcd, m1.*, m3.* FROM ( SELECT t1.model_id, t1.model_nm, t1.model_sort_odrg FROM dtmeta.tb_meta_model t1 WHERE t1.up_model_id = 'Class' AND t1.model_type_mtcd = 'object_type' AND t1.model_data_sttus_mtcd = 'use'
AND t1.model_id = #{typeModelId}
) m1 INNER JOIN dtmeta.tb_portal_code m2 ON m2.mtcd_grp_id = 'MCG00009' AND m2.mtcd_use_yn = 'Y' LEFT OUTER JOIN ( SELECT r1.rdf_mappg_id, r1.rdf_form_mtcd, r1.type_model_id, r1.rdf_mappg_nm, r2.rdf_class_id, r2.rdf_cond_odrg FROM dtmeta.tb_rdf_mapping r1 LEFT OUTER JOIN dtmeta.tb_rdf_mappingmodel r2 ON r1.rdf_mappg_id = r2.rdf_mappg_id LEFT OUTER JOIN dtmeta.tb_rdf_class r3 ON r2.rdf_class_id = r3.rdf_class_id LEFT OUTER JOIN dtmeta.tb_rdf_namespace r4 ON r3.rdf_nmsp_id = r4.rdf_nmsp_id WHERE r1.rdf_form_mtcd = 'dcat' AND r1.rdf_mappg_data_sttus_mtcd = 'use' ) m3 ON m2.mtcd = m3.rdf_form_mtcd AND m1.model_id = m3.type_model_id WHERE m2.mtcd = #{rdfFormMtcd}
AND m3.rdf_mappg_id IS NOT NULL
AND m3.rdf_mappg_id IS NULL
) subquery GROUP BY rdf_form_mtcd_nm, mtcd, model_id, model_nm
HAVING COALESCE(MAX(rdf_rep_model_yn), 'N') = #{rdfRepModelYn}
) count_subquery;

SELECT /* SQL_ID: RdfMappingMapper.selectRdfMappingStatusList */ rdf_form_mtcd_nm, mtcd, model_id, model_nm, MAX(model_sort_odrg) AS model_sort_odrg, MAX(rdf_mappg_id) AS rdf_mappg_id, MAX(rdf_form_mtcd) AS rdf_form_mtcd, MAX(type_model_id) AS type_model_id, MAX(rdf_mappg_nm) AS rdf_mappg_nm, STRING_AGG(rdf_class_id, ',' ORDER BY rdf_cond_odrg) AS rdf_class_id, STRING_AGG(rdf_class, ',' ORDER BY rdf_cond_odrg) AS rdf_class, CASE WHEN MAX(rdf_mappg_id) IS NOT NULL THEN 'Y' ELSE 'N' END AS rdf_mappg_yn FROM ( SELECT m2.mtcd_nm AS rdf_form_mtcd_nm, m2.mtcd AS mtcd, m1.*, m3.* FROM ( SELECT t1.model_id, t1.model_nm, t1.model_sort_odrg FROM dtmeta.tb_meta_model t1 WHERE t1.up_model_id = 'Class' AND t1.model_type_mtcd = 'object_type' AND t1.model_data_sttus_mtcd = 'use'
AND t1.model_id = #{typeModelId}
) m1 INNER JOIN dtmeta.tb_portal_code m2 ON m2.mtcd_grp_id = 'MCG00009' AND m2.mtcd_use_yn = 'Y' LEFT OUTER JOIN ( SELECT r1.rdf_mappg_id, r1.rdf_form_mtcd, r1.type_model_id, r1.rdf_mappg_nm, r2.rdf_class_id, CASE WHEN r2.rdf_class_id IS NOT NULL THEN CONCAT(r4.rdf_nmsp_pfix, ':', r3.rdf_class_nm, CASE WHEN r2.rdf_rep_model_yn = 'Y' THEN ' (대표)' ELSE '' END) ELSE NULL END AS rdf_class, r2.rdf_cond_odrg FROM dtmeta.tb_rdf_mapping r1 LEFT OUTER JOIN dtmeta.tb_rdf_mappingmodel r2 ON r1.rdf_mappg_id = r2.rdf_mappg_id LEFT OUTER JOIN dtmeta.tb_rdf_class r3 ON r2.rdf_class_id = r3.rdf_class_id LEFT OUTER JOIN dtmeta.tb_rdf_namespace r4 ON r3.rdf_nmsp_id = r4.rdf_nmsp_id WHERE r1.rdf_form_mtcd = 'dcat' AND r1.rdf_mappg_data_sttus_mtcd = 'use' ) m3 ON m2.mtcd = m3.rdf_form_mtcd AND m1.model_id = m3.type_model_id WHERE m2.mtcd = #{rdfFormMtcd}
AND m3.rdf_mappg_id IS NOT NULL
AND m3.rdf_mappg_id IS NULL
) subquery GROUP BY rdf_form_mtcd_nm, mtcd, model_id, model_nm
HAVING COALESCE(MAX(rdf_rep_model_yn), 'N') = #{rdfRepModelYn}
ORDER BY MAX(model_sort_odrg)

