		UPDATE /* SQL_ID: RdfMappingMapper.updateRdfMapping */
       		dtmeta.tb_rdf_mapping
	   	SET 
	   		rdf_mappg_amdr_id = #{rdfMappgAmdrId}
            , rdf_mappg_amdr_nm	= #{rdfMappgAmdrNm}
            , rdf_mappg_amd_dt = current_timestamp
           	, rdf_mappg_nm = #{rdfMappgNm}            
		 WHERE 
		 	rdf_mappg_id = #{rdfMappgId}

		UPDATE /* SQL_ID: RdfMappingMapper.deleteRdfMapping */
       		dtmeta.tb_rdf_mapping
	   	SET 
	   		rdf_mappg_amdr_id = #{rdfMappgAmdrId}
            , rdf_mappg_amdr_nm	= #{rdfMappgAmdrNm}
            , rdf_mappg_amd_dt = current_timestamp  
           	, rdf_mappg_data_sttus_mtcd = 'disuse'
		 WHERE 
		 	rdf_mappg_id = #{rdfMappgId}

