SELECT CONCAT('RMP', EXTRACT(EPOCH FROM now())::int, LPAD(CAST(NEXTVAL('dtmeta.seq_tb_rdf_common') AS varchar), 4, '0'))    

INSERT /* SQL_ID: RdfMappingMapper.insertRdfMapping */
        INTO dtmeta.tb_rdf_mapping
        ( rdf_mappg_id
        , rdf_form_mtcd
        , type_model_id
        , rdf_mappg_nm
        , rdf_mappg_data_sttus_mtcd
        , rdf_mappg_regr_id
        , rdf_mappg_regr_nm
        , rdf_mappg_reg_dt
        , rdf_mappg_amdr_id
        , rdf_mappg_amdr_nm
        , rdf_mappg_amd_dt
        ) VALUES
        (
          #{rdfMappgId}
        , #{rdfFormMtcd}
        , #{typeModelId}
        , #{rdfMappgNm}
        , #{rdfMappgDataSttusMtcd}
        , #{rdfMappgRegrId}
        , #{rdfMappgRegrNm}
        , current_timestamp
        , #{rdfMappgAmdrId}
        , #{rdfMappgAmdrNm}
        , current_timestamp
        )


	SELECT CONCAT('RMD', EXTRACT(EPOCH FROM now())::int, LPAD(CAST(NEXTVAL('dtmeta.seq_tb_rdf_common') AS varchar), 4, '0'))	

	INSERT /* SQL_ID: RdfMappingMapper.insertRdfMappingModel */
		INTO dtmeta.tb_rdf_mappingmodel
		( rdf_mappg_model_id
		, rdf_mappg_id
		, rdf_class_id
		, rdf_rep_model_yn
		, rdf_cond_odrg
		, cond_model_id
		, rdf_mappg_model_regr_id
		, rdf_mappg_model_regr_nm
		, rdf_mappg_model_reg_dt
		, rdf_mappg_model_amdr_id
		, rdf_mappg_model_amdr_nm
		, rdf_mappg_model_amd_dt
		) VALUES
		(
	 	  #{rdfMappgModelId}
	 	, #{rdfMappgId}
	 	, #{rdfClassId}
	 	, #{rdfRepModelYn}
	 	, #{rdfCondOdrg}
	 	, #{condModelId}
	 	, #{rdfMappgModelRegrId}
	 	, #{rdfMappgModelRegrNm}
 		, current_timestamp
	 	, #{rdfMappgModelAmdrId}
	 	, #{rdfMappgModelAmdrNm}
 		, current_timestamp
	 	)

