			rdf_cond_odrg = #{rdfCondOdrg}
			, rdf_class_id = #{rdfClassId}
			, rdf_rep_model_yn = #{rdfRepModelYn}
			, cond_model_id = #{condModelId}
	 	WHERE 
		 	rdf_mappg_model_id = #{rdfMappgModelId}

