/* SQL_ID: RdfMappingMapper.selectRdfMappingTreeList */ WITH RECURSIVE treeview AS ( SELECT 'ROOT' AS node_id , '' AS up_node_id , 'ROOT' AS up_node_div_id , 0 AS node_odrg , NULL AS node_objt_mappg_yn , NULL AS node_objt_rdf_class_id , 'c' AS node_div , t1.rdf_class_id AS node_div_id , concat(t3.rdf_nmsp_pfix, ':', t2.rdf_class_nm) AS node_nm , NULL AS node_objt_id , NULL AS type_model_id , 0 AS depth , ARRAY ['ROOT'::text] AS id_path , ARRAY [0::int4] AS odrg_path , FALSE AS cycle FROM dtmeta.tb_rdf_mappingmodel t1 INNER JOIN dtmeta.tb_rdf_class t2 ON t1.rdf_class_id = t2.rdf_class_id INNER JOIN dtmeta.tb_rdf_namespace t3 ON t2.rdf_nmsp_id = t3.rdf_nmsp_id WHERE 1=1
AND t1.rdf_mappg_model_id = #{rdfMappgModelId}
UNION ALL SELECT m1.node_id::text , m1.up_node_id::TEXT , m2.node_div_id::TEXT AS up_node_div_id , m1.node_odrg::int4 , m1.node_objt_mappg_yn::text , m1.node_objt_rdf_class_id::text , m1.node_div , m1.node_div_id , m1.node_nm , m1.node_objt_id::text , m1.type_model_id::text , m2.depth + 1 , ARRAY_APPEND(m2.id_path, m1.node_id::text) , ARRAY_APPEND(m2.odrg_path, m1.node_odrg::int4) , m1.node_id = ANY(m2.id_path) FROM ( SELECT CASE WHEN t4.up_rdf_mappg_rule_id = 'ROOT' THEN 'ROOT' ELSE t4.up_rdf_mappg_rule_id || '_objt' END AS up_node_id , t4.rdf_mappg_rule_id AS node_id , t4.rdf_mappg_rule_odrg AS node_odrg , t4.objt_data_mappg_yn AS node_objt_mappg_yn , t4.objt_rdf_class_id AS node_objt_rdf_class_id , 'p' AS node_div , t4.rdf_prpty_id AS node_div_id , CONCAT(t3.rdf_nmsp_pfix, ':', t5.rdf_prpty_nm) AS node_nm , t4.objt_prpty_id AS node_objt_id , NULL AS type_model_id FROM dtmeta.tb_rdf_mappingrule t4 INNER JOIN dtmeta.tb_rdf_property t5 ON t4.rdf_prpty_id = t5.rdf_prpty_id INNER JOIN dtmeta.tb_rdf_namespace t3 ON t5.rdf_nmsp_id = t3.rdf_nmsp_id WHERE 1=1
AND t4.rdf_mappg_model_id = #{rdfMappgModelId}
UNION ALL SELECT t4.rdf_mappg_rule_id AS up_node_id , t4.rdf_mappg_rule_id || '_objt' AS node_id , t4.rdf_mappg_rule_odrg AS node_odrg , t4.objt_data_mappg_yn AS node_objt_mappg_yn , t4.objt_rdf_class_id AS node_objt_rdf_class_id , CASE WHEN t4.objt_rdf_class_id IS NOT NULL THEN 'c' ELSE 'm' END AS node_div , COALESCE(t4.objt_rdf_class_id, t6.rdf_class_id) AS node_div_id , CASE WHEN t4.objt_rdf_class_id IS NOT NULL THEN CONCAT(t3.rdf_nmsp_pfix, ':', t2.rdf_class_nm) ELSE t6.rdf_class END AS node_nm , COALESCE(t4.objt_rdf_class_id, t4.objt_rdf_mappg_id) AS node_objt_id , t6.type_model_id AS type_model_id FROM dtmeta.tb_rdf_mappingrule t4 LEFT OUTER JOIN dtmeta.tb_rdf_class t2 ON t4.objt_rdf_class_id = t2.rdf_class_id LEFT OUTER JOIN dtmeta.tb_rdf_namespace t3 ON t2.rdf_nmsp_id = t3.rdf_nmsp_id LEFT OUTER JOIN ( SELECT a1.rdf_mappg_id , a1.type_model_id , a2.rdf_class_id , CONCAT(a4.rdf_nmsp_pfix, ':', a3.rdf_class_nm) AS rdf_class FROM dtmeta.tb_rdf_mapping a1 LEFT OUTER JOIN dtmeta.tb_rdf_mappingmodel a2 ON a1.rdf_mappg_id = a2.rdf_mappg_id LEFT OUTER JOIN dtmeta.tb_rdf_class a3 ON a2.rdf_class_id = a3.rdf_class_id LEFT OUTER JOIN dtmeta.tb_rdf_namespace a4 ON a3.rdf_nmsp_id = a4.rdf_nmsp_id WHERE 1=1 AND a1.rdf_mappg_data_sttus_mtcd = 'use' AND a2.rdf_rep_model_yn = 'Y' ) t6 ON t4.objt_rdf_mappg_id = t6.rdf_mappg_id WHERE 1=1
AND t4.rdf_mappg_model_id = #{rdfMappgModelId}
AND (t4.objt_rdf_class_id IS NOT NULL OR t4.objt_rdf_mappg_id IS NOT NULL) ) m1 INNER JOIN treeview m2 ON m1.up_node_id = m2.node_id WHERE NOT CYCLE ) SELECT node_id , up_node_id , up_node_div_id , node_odrg , node_objt_mappg_yn , node_objt_rdf_class_id , node_div , node_div_id , node_nm , node_objt_id , type_model_id FROM treeview m WHERE 1=1
AND node_div = #{nodeDiv}
AND up_node_div_id = #{upNodeDivId}
AND node_div_id = #{nodeDivId}
ORDER BY odrg_path
